param([string]$AssemblyPath='H:\Darkorbit-Cpp\build\server-events\DarkOrbit.exe')
$ErrorActionPreference='Stop';$asm=[Reflection.Assembly]::LoadFrom($AssemblyPath);$null=[Reflection.Assembly]::LoadFrom((Join-Path (Split-Path $AssemblyPath) 'MySql.Data.dll'));$db=New-Object MySql.Data.MySqlClient.MySqlConnection 'Server=127.0.0.1;User ID=root;SslMode=None';$db.Open();$name='do_logbook_test_'+[Guid]::NewGuid().ToString('N');$field=$asm.GetType('Ow.Managers.MySQLManager.SqlDatabaseManager').GetField('ConnectionString');$original=$field.GetValue($null)
function Query($sql){$q=$db.CreateCommand();$q.CommandText=$sql;try{$q.ExecuteScalar()}finally{$q.Dispose()}}
try{$null=Query "CREATE DATABASE $name CHARACTER SET utf8mb4";$db.ChangeDatabase($name);$field.SetValue($null,"Server=127.0.0.1;Database=$name;User ID=root;SslMode=None;CharSet=utf8mb4");$p=[Runtime.Serialization.FormatterServices]::GetUninitializedObject($asm.GetType('Ow.Game.Objects.Player'));$asm.GetType('Ow.Game.Objects.Attackable').GetField('<Id>k__BackingField',[Reflection.BindingFlags]'NonPublic,Instance').SetValue($p,987654321);$write=$asm.GetType('Ow.Managers.QueryManager').GetMethod('WriteLogbook');$message="Conquista: piloto's \ teste";$null=$write.Invoke($null,@($p,'achievement',$message));$null=$write.Invoke($null,@($p,'game','Entrada no mapa.'));if((Query 'SELECT COUNT(*) FROM player_logbook WHERE user_id=987654321') -ne 2){throw 'Server logbook records missing'};if((Query 'SELECT message FROM player_logbook ORDER BY id LIMIT 1') -cne $message){throw 'Logbook text escaping corrupted'};Write-Output 'Server logbook passed: persistent records, own user ID, quote/backslash text and schema initialization.'}finally{$field.SetValue($null,$original);$null=Query "DROP DATABASE $name";$db.Dispose()}
